        "category": "AI",
        "status": "published",
        "image": "/images/ai_plugin_maker_minecraft.webp",
        "image_alt": "AI Plugin Maker Minecraft development workspace showing code editor and server dashboard",
        "image_caption": "AI Plugin Maker Minecraft: Using Artificial Intelligence to Build Server Plugins",
